-- ========== 3. 刷数：编号精确匹配（内置 + TFDA，含软删行一并刷齐） ==========
UPDATE foods f
JOIN cat18_map m ON f.code = m.code
SET f.category_code = m.category_code, f.category_name = m.category_name;

-- ========== 4. 共建存量（code 为空的旧 10 类名行，先验转换；重跑以旧类名为守卫不二次命中） ==========
-- 注意: MySQL SET 赋值从左到右求值，category_name 的 CASE 须在 category_code 改写前引用原值，故 name 在前
UPDATE foods
SET category_name = CASE category_code
        WHEN '01' THEN '谷物类'
        WHEN '02' THEN '肉类'
        WHEN '03' THEN '蛋类'
        WHEN '04' THEN '鱼贝类'
        WHEN '05' THEN '豆类'
        WHEN '06' THEN '蔬菜类'
        WHEN '07' THEN '菇类'
        WHEN '08' THEN '水果类'
        WHEN '09' THEN '坚果及种子类'
        WHEN '10' THEN '油脂类'
    END,
    category_code = CASE category_code
        WHEN '01' THEN '02'
        WHEN '02' THEN '03'
        WHEN '03' THEN '05'
        WHEN '04' THEN '04'
        WHEN '05' THEN '07'
        WHEN '06' THEN '08'
        WHEN '07' THEN '09'
        WHEN '08' THEN '11'
        WHEN '09' THEN '12'
        WHEN '10' THEN '13'
    END
WHERE code IS NULL AND category_name IN ('谷薯杂豆·主食', '畜禽肉及制品', '蛋奶及制品', '水产及制品', '大豆及制品', '蔬菜', '菌藻', '水果', '坚果·种子', '油脂·调味·饮品');

-- ========== 5. 收尾：清临时表 + 版本账补账（幂等） ==========
DROP TEMPORARY TABLE IF EXISTS cat18_map;
